#!/usr/bin/env python3
"""Writes syahi/kit.h from tools/kits.py: the models' names and labels, their
defaults and the default kit on keys 53..76.

    python3 syahi/tools/make_kit.py
"""
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import kits  # noqa: E402

HERE = pathlib.Path(__file__).resolve().parent.parent


def main():
    m = kits.MODELS
    out = ["#pragma once",
           "// Generated by tools/make_kit.py from tools/kits.py: edit those, then regenerate.",
           "#include <opxy/types.hpp>",
           "",
           "namespace syahi {",
           "namespace kit {",
           "using opxy::u32;",
           f"const u32 keys = 24;",
           f"const u32 models = {len(m)};",
           "// The models as the header names them, and their controls' labels.",
           "const char* const model_names[models] = {" + ", ".join(f'"{n}"' for n in m) + "};",
           "const char* const labels[models][8] = {"]
    for n in m:
        out.append("    {" + ", ".join(f'"{x}"' for x in kits.LABELS[n]) + "},")
    out += ["};", "// Each model's defaults, 0..127.", "const unsigned char model_defaults[models][8] = {"]
    for n in m:
        out.append("    {" + ", ".join(map(str, kits.DEFAULTS[n])) + f"}},   // {n}")
    out += ["};", "// The default kit: each key's model and controls.",
            "const unsigned char key_model[keys] = {" + ", ".join(str(m.index(k[1])) for k in kits.DEFAULT_KIT) + "};",
            "const unsigned char key_values[keys][8] = {"]
    for i, (role, model, values, _choke) in enumerate(kits.DEFAULT_KIT):
        out.append("    {" + ", ".join(map(str, values)) + f"}},   // {53 + i} {role}: {model}")
    out += ["};",
            "// The same, in the shape MD KIT's kit.h gives (a screen checker can read it).",
            "struct Model { const char* name; const char* labels[8]; };",
            "const Model model[models] = {"]
    for n in m:
        out.append(f'    {{"{n}", {{' + ", ".join(f'"{x}"' for x in kits.LABELS[n]) + "}},")
    out += ["};",
            "// A key's stored controls as the SDK hands them to render (Q31, 0..127 << 24).",
            "static inline void key_controls(u32 key, opxy::i32* values) {",
            "    for (u32 c = 0; c < 8; ++c) values[c] = key_values[key][c] >= 127 ? 0x7fffffff : static_cast<opxy::i32>(static_cast<u32>(key_values[key][c]) << 24);",
            "}",
            "}", "}", ""]
    (HERE / "kit.h").write_text("\n".join(out))
    print("wrote", HERE / "kit.h")


if __name__ == "__main__":
    main()
